package com.ias.approval;
import com.ias.trust.Problem;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.sql.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FinanceFeeRuleTest {
 DriverManagerDataSource ds;JdbcTemplate db;
 @BeforeEach void prepare()throws Exception{ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);try(var c=ds.getConnection();var in=getClass().getResourceAsStream("/db/migration/V5__published_fee_rule.sql")){c.createStatement().execute(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("CHARACTER SET ascii COLLATE ascii_bin","").replace("ENGINE=InnoDB",""));}}
 FinanceFeeRulePublisher.Plan plan(String tenant,String version,String threshold){return new FinanceFeeRulePublisher.Plan(UUID.randomUUID().toString(),tenant,version,threshold);}
 Map<String,Object> publish(FinanceFeeRulePublisher.Plan p)throws Exception{try(var c=ds.getConnection()){return FinanceFeeRulePublisher.publish(c,p,"restricted-operator-plan");}}
 @Test void unpublishedRuleNeverBecomesDefaultThreshold(){assertEquals("FEE_RULE_UNAVAILABLE",assertThrows(Problem.class,()->FinanceFeeRuleController.published(db,7)).code);}
 @Test void immutablePublicationOriginalUuidAndTenantSpecificCurrentRule()throws Exception{var one=plan("7","FEE_V1","10000");assertEquals(publish(one),publish(one));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM approval_fee_rule_publication",Integer.class));publish(plan("8","OTHER_V1","999999"));assertEquals("10000",FinanceFeeRuleController.published(db,7).get("thresholdCents"));publish(plan("7","FEE_V2","20000"));assertEquals("FEE_V2",FinanceFeeRuleController.published(db,7).get("version"));assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM approval_fee_rule_publication",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM approval_fee_rule_publication WHERE tenant_id=7 AND rule_version='FEE_V1'",Integer.class));}
 @Test void changedOriginalOperationAndDuplicateVersionCannotRewriteThreshold()throws Exception{var p=plan("7","FEE_V1","10000");publish(p);assertThrows(Exception.class,()->publish(new FinanceFeeRulePublisher.Plan(p.operationId(),"7","FEE_V1","1")));assertThrows(Exception.class,()->publish(plan("7","FEE_V1","1")));assertEquals("10000",FinanceFeeRuleController.published(db,7).get("thresholdCents"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM approval_fee_rule_publication",Integer.class));}
}
